from pathlib import Path
import json,time

root=Path.home()/".local/share/prediction-project-executor/campaigns/FULL-A2Z-LIVE-20261004-V4"
task="A2Z-V4-ASTRA-PREBUILD-DIRECT-20261007-R4P2"
p=root/"model_results"/(task+".json")
deadline=time.time()+120
while time.time()<deadline and not p.is_file():
    time.sleep(2)
if not p.is_file():
    raise RuntimeError("PREBUILD_GATE=PENDING_TIMEOUT")

o=json.loads(p.read_text(encoding="utf-8"))
if o.get("task_id")!=task:
    raise RuntimeError("PREBUILD_GATE=INVALID_TASK")
if o.get("phase")!="ASTRA_PREBUILD":
    raise RuntimeError("PREBUILD_GATE=INVALID_PHASE:"+str(o.get("phase")))
if o.get("model")!="gpt-6-astra":
    raise RuntimeError("PREBUILD_GATE=INVALID_MODEL:"+str(o.get("model")))
if o.get("model_policy")!="ASTRA_EXACT":
    raise RuntimeError("PREBUILD_GATE=INVALID_POLICY:"+str(o.get("model_policy")))

f=o.get("final")
r=json.loads(f) if isinstance(f,str) else f
if not isinstance(r,dict):
    raise RuntimeError("PREBUILD_GATE=INVALID_REVIEW")
d=r.get("decision")
if d not in {"APPROVE","REVISE","REJECT"}:
    raise RuntimeError("PREBUILD_GATE=INVALID_DECISION:"+str(d))
if r.get("candidate_id")!="AUTO-DISCOVERY-54d13314c7879b58e46d":
    raise RuntimeError("PREBUILD_GATE=CANDIDATE_MISMATCH")
if r.get("phase")!="PREBUILD":
    raise RuntimeError("PREBUILD_GATE=REVIEW_PHASE_MISMATCH")
b=r.get("binding_sha256")
if not isinstance(b,str) or len(b)!=64:
    raise RuntimeError("PREBUILD_GATE=BINDING_INVALID")
finding=str(r.get("finding") or "").replace("\n"," ")[:350]
next_action=str(r.get("next_action") or "").replace("\n"," ")[:350]
raise RuntimeError("PREBUILD_GATE="+d+" binding="+b+" finding="+finding+" next="+next_action)
